def _load_embedded(name,payload):
    mod=types.ModuleType(name); mod.__file__=f'<embedded-{name}>'; sys.modules[name]=mod
    raw=zlib.decompress(base64.b64decode(payload.encode()))
    exec(compile(raw,mod.__file__,'exec'),mod.__dict__)
    return mod

V45=_load_embedded('v46_embedded_v45',V45_PAYLOAD)
DESIGN_TEXT=zlib.decompress(base64.b64decode(DESIGN_PAYLOAD.encode())).decode()
