# ------------------------------ utilities ---------------------------------
def sha_bytes(b): return hashlib.sha256(bytes(b)).hexdigest()
def sha_json(obj): return sha_bytes(json.dumps(obj,sort_keys=True,separators=(',',':'),default=str).encode())
def source_sha(): return sha_bytes(SOURCE.read_bytes())

def atomic_json(path,obj):
    path=Path(path); path.parent.mkdir(parents=True,exist_ok=True); tmp=path.with_suffix(path.suffix+'.tmp')
    with tmp.open('w') as fh:
        json.dump(obj,fh,indent=1,sort_keys=True,default=str); fh.flush(); os.fsync(fh.fileno())
    os.replace(tmp,path)

def atomic_gzip_json(path,obj):
    path=Path(path); path.parent.mkdir(parents=True,exist_ok=True); tmp=path.with_suffix(path.suffix+'.tmp')
    with gzip.open(tmp,'wt') as fh: json.dump(obj,fh,separators=(',',':'),default=str)
    os.replace(tmp,path)

def load_gzip_json(path):
    with gzip.open(path,'rt') as fh: return json.load(fh)

def atomic_pickle(path,obj):
    path=Path(path); path.parent.mkdir(parents=True,exist_ok=True); tmp=path.with_suffix(path.suffix+'.tmp')
    with tmp.open('wb') as fh:
        pickle.dump(obj,fh,protocol=pickle.HIGHEST_PROTOCOL); fh.flush(); os.fsync(fh.fileno())
    os.replace(tmp,path)

def load_pickle(path):
    class Compat(pickle.Unpickler):
        def find_class(self,module,name):
            if module in ('__main__','v46m','v46mod','v46z') and name in globals(): return globals()[name]
            return super().find_class(module,name)
    with Path(path).open('rb') as fh: return Compat(fh).load()

def current_rss_bytes():
    r=int(resource.getrusage(resource.RUSAGE_SELF).ru_maxrss)
    return r if sys.platform=='darwin' else r*1024

def interval(vals):
    v=[float(x) for x in vals if x is not None and math.isfinite(float(x))]; n=len(v)
    if not v: return {'n':0,'mean':None,'low':None,'high':None}
    mean=statistics.mean(v)
    if n<2:return {'n':n,'mean':mean,'low':None,'high':None}
    q=float(student_t.ppf(.975,n-1)) if student_t is not None else {1:12.706,2:4.303,3:3.182,4:2.776,5:2.571,6:2.447,7:2.365,8:2.306,9:2.262,10:2.228,11:2.201,12:2.179,13:2.160,14:2.145,15:2.131}.get(n-1,1.96)
    half=q*statistics.stdev(v)/math.sqrt(n)
    return {'n':n,'mean':mean,'low':mean-half,'high':mean+half}

def write_csv(path,rows,gz=False):
    path=Path(path); path.parent.mkdir(parents=True,exist_ok=True)
    rows=list(rows)
    if not rows:
        path.write_text(''); return
    fields=[]
    for r in rows:
        for k in r:
            if k not in fields: fields.append(k)
    opener=(lambda p: gzip.open(p,'wt',newline='')) if gz else (lambda p: open(p,'w',newline=''))
    with opener(path) as fh:
        w=csv.DictWriter(fh,fieldnames=fields,extrasaction='ignore'); w.writeheader()
        for r in rows:w.writerow({k:r.get(k) for k in fields})

def paired(terminal,left,right,key,load=PRIMARY_LOAD):
    by=collections.defaultdict(dict)
    for r in terminal:
        if int(r['load'])==int(load): by[int(r['seed'])][r['arm']]=r
    diffs=[]
    for s,a in sorted(by.items()):
        x,y=a.get(left),a.get(right)
        if x is not None and y is not None and x.get(key) is not None and y.get(key) is not None:
            diffs.append(float(x[key])-float(y[key]))
    return interval(diffs)

def psoft(scores): return V45.psoft(scores)
def psoft_batch(scores): return V45.psoft_batch(scores)

def deployed_prob(fast_scores,slow_scores): return .5*psoft(fast_scores)+.5*psoft(slow_scores)

# ------------------------- Candidate-C development -------------------------
def development_identity(seed,smoke=False):
    return sha_json({'version':VERSION,'source':source_sha(),'design':DESIGN_SHA256,
                     'seed':int(seed),'smoke':bool(smoke),'pair_rank':V45.PAIR_RANK,
                     'pair_eta':V45.PAIR_ETA,'pair_tau':V45.PAIR_TAU,
                     'pair_topk':V45.PAIR_TOPK,'dev_ids':32 if smoke else V45.DEV_IDENTITIES})

def save_development(out_dir,dev,smoke=False):
    ddir=Path(out_dir)/'development'; ddir.mkdir(parents=True,exist_ok=True); seed=int(dev['seed'])
    npz=ddir/f'S{seed}.npz'; meta=ddir/f'S{seed}.json'; tmp=npz.with_suffix('.npz.tmp')
    with open(tmp,'wb') as fh: np.savez_compressed(fh,U_PAIR=dev['U_PAIR'])
    os.replace(tmp,npz)
    md={k:v for k,v in dev.items() if not k.startswith('U_') and k not in ('dev_identity_keys','audit')}
    md['audit_same_identity_count']=sum(int(x['same_identity']) for x in dev['audit'])
    md['audit_count']=len(dev['audit'])
    md['dev_identity_keys_b64']=[base64.b64encode(x).decode() for x in dev['dev_identity_keys']]
    md['development_identity']=development_identity(seed,smoke); md['npz_sha256']=sha_bytes(npz.read_bytes())
    atomic_json(meta,md); return md

def load_development(out_dir,seed,smoke=False):
    ddir=Path(out_dir)/'development'; npz=ddir/f'S{seed}.npz'; meta=ddir/f'S{seed}.json'
    md=json.loads(meta.read_text())
    if md.get('development_identity')!=development_identity(seed,smoke): raise RuntimeError('development identity mismatch')
    if md.get('npz_sha256')!=sha_bytes(npz.read_bytes()): raise RuntimeError('development hash mismatch')
    with np.load(npz) as z: U=np.array(z['U_PAIR'],copy=True)
    keys=[base64.b64decode(x) for x in md['dev_identity_keys_b64']]
    return md,U,keys

def run_development_worker(task):
    seed,out_dir,smoke=task; out_dir=Path(out_dir); meta=out_dir/'development'/f'S{seed}.json'
    if meta.exists():
        try:
            md,_,_=load_development(out_dir,seed,smoke); return {'seed':seed,'status':'reused','pair_updates':md['pair_updates']}
        except Exception: pass
    t=time.time(); dev=V45.learn_development(seed,smoke); md=save_development(out_dir,dev,smoke)
    return {'seed':seed,'status':'new','pair_updates':md['pair_updates'],'seconds':time.time()-t}

# -------------------------- common BASE-miss schedule -----------------------
def build_base_schedule(seed,stream):
    enc=V39.Encoder(seed,'last_fd'); base=V39.Learner('full'); hist=bytearray(); idx=0
    eligible=set(); event_meta={}
    for row in stream['rows']:
        for pos,y in enumerate(row['raw']):
            z,b=enc.encode(hist); sb=base.scores(z,b); miss=(int(np.argmax(sb))!=int(y))
            if miss and len(hist)>=12: eligible.add(idx)
            event_meta[idx]={'wave':row['wave'],'pos':int(pos),'kind':row['kind'],
                             'key_id':int(row['key_id']),'y':int(y)}
            base.observe(z,b,int(y)); hist.append(int(y))
            if len(hist)>12: del hist[:-12]
            idx+=1
    return {'ordinary':eligible,'event_meta':event_meta,'ordinary_hash':sha_json(sorted(eligible))}

def sampled_events(seed,event_set,maximum=INTERFERENCE_MAX):
    def key(i):return hashlib.sha256(f'v46:{seed}:{int(i)}'.encode()).digest()
    return set(sorted(event_set,key=key)[:min(maximum,len(event_set))])

# -------------------------- learned pathway system --------------------------
def _row_normalize(a): return a/np.maximum(np.linalg.norm(a,axis=1,keepdims=True),1e-12)
def _softmax_small(a):
    a=np.asarray(a,float); a=a-a.max(); e=np.exp(a); return e/max(float(e.sum()),1e-300)

def _jaccard(a,b):
    a=set(map(int,a)); b=set(map(int,b)); return len(a&b)/len(a|b) if (a or b) else 0.

class PathwaySystem:
    def __init__(self,seed,U_pair,arm_order=ARMS):
        self.seed=int(seed); self.U=np.asarray(U_pair,dtype=np.float64); self.arms=tuple(arm_order)
        if set(self.arms)!=set(ARMS): raise ValueError('arm_order must be a permutation of ARMS')
        self.ai={a:i for i,a in enumerate(self.arms)}
        rr=np.random.default_rng(seed+1000+3604096)
        self.contacts=np.stack([rr.choice(D,SLOW_CONTACTS,replace=False) for _ in range(SLOW_UNITS)]).astype(np.int16)
        self.proj=rr.normal(size=(SLOW_UNITS,SLOW_CONTACTS)); self.proj/=np.linalg.norm(self.proj,axis=1,keepdims=True)
        pr=np.random.default_rng(seed+460046); perm=pr.permutation(SLOW_UNITS).astype(np.int16)
        self.path_blocks=perm.reshape(PATHWAYS,UNITS_PER_PATH)
        pg=np.random.default_rng(seed+460047); init=_row_normalize(pg.normal(size=(PATHWAYS,D)))
        self.initial_prototypes=init.copy(); self.prototypes=np.repeat(init[None,:,:],len(self.arms),axis=0)
        self.usage=np.full((len(self.arms),PATHWAYS),ROUTES_PER_EVENT/PATHWAYS,dtype=np.float64)
        self.W=np.zeros((len(self.arms),SLOW_UNITS,OUTPUTS),dtype=np.float64)
        self.updates=np.zeros(len(self.arms),dtype=np.int64)
        self.route_events=np.zeros(len(self.arms),dtype=np.int64)
        self.selection_counts=np.zeros((len(self.arms),PATHWAYS),dtype=np.int64)
        self.path_write_counts=np.zeros((len(self.arms),PATHWAYS),dtype=np.int64)
        self.resp_entropy_sum=np.zeros(len(self.arms)); self.resp_entropy_n=np.zeros(len(self.arms),dtype=np.int64)
        self.prior_entropy_sum=np.zeros(len(self.arms)); self.prior_entropy_n=np.zeros(len(self.arms),dtype=np.int64)
        self.shuffle_multiset_max_error=0.
        self._cache=collections.OrderedDict(); self.cache_cap=8192

    def clear_transient(self): self._cache.clear()

    def features(self,c):
        c=bytes(c)[-12:]
        if len(c)!=12: raise ValueError('full context required')
        if c in self._cache:
            q=self._cache.pop(c); self._cache[c]=q; return q
        x=V45.clean_rep(c,self.U)
        drives=np.tanh(np.einsum('uc,uc->u',x[self.contacts],self.proj,optimize=True))
        gi=np.argpartition(-np.abs(drives),SLOW_K-1)[:SLOW_K]; gi=np.sort(gi)
        gv=drives[gi]; gv=gv/max(float(np.linalg.norm(gv)),1e-12)
        pix=[]; pvals=[]
        for p in range(PATHWAYS):
            block=self.path_blocks[p].astype(np.int64)
            local=drives[block]; jj=np.argpartition(-np.abs(local),UNITS_PER_ROUTE-1)[:UNITS_PER_ROUTE]
            ix=np.sort(block[jj]); vals=drives[ix]
            pix.append(ix.astype(np.int16)); pvals.append(vals.astype(np.float64))
        q={'x':x,'drives':drives,'global_ix':gi.astype(np.int16),'global_v':gv,
           'path_ix':np.stack(pix),'path_vals':np.stack(pvals)}
        self._cache[c]=q
        if len(self._cache)>self.cache_cap:self._cache.popitem(last=False)
        return q

    def _hash_paths(self,c):
        d=hashlib.sha256(f'{self.seed}:v46hash:'.encode()+bytes(c)[-12:]).digest()[:8]
        rg=np.random.default_rng(int.from_bytes(d,'little'))
        return np.sort(rg.choice(PATHWAYS,size=ROUTES_PER_EVENT,replace=False)).astype(np.int64)

    def _selected_route(self,feat,paths):
        ix=np.concatenate([feat['path_ix'][int(p)].astype(np.int64) for p in paths])
        v=np.concatenate([feat['path_vals'][int(p)] for p in paths]).astype(np.float64)
        v=v/max(float(np.linalg.norm(v)),1e-12)
        return ix,v

    def route(self,arm,c,event_index,read_only=False):
        ai=self.ai[arm]; feat=self.features(c); x=feat['x']
        if arm=='GLOBAL-PAIR':
            ix=feat['global_ix'].astype(np.int64); v=feat['global_v']; s=v@self.W[ai,ix,:]
            return {'arm':arm,'x':x,'paths':None,'ix':ix,'v':v,'slow_scores':s,'g':None,'local_scores':None}
        if arm=='HASH-ROUTE':
            paths=self._hash_paths(c); g=np.full(ROUTES_PER_EVENT,1./ROUTES_PER_EVENT)
        else:
            logits=self.prototypes[ai]@x-HOMEOSTASIS_LAMBDA*(self.usage[ai]-ROUTES_PER_EVENT/PATHWAYS)
            paths=np.argpartition(-logits,ROUTES_PER_EVENT-1)[:ROUTES_PER_EVENT]
            paths=paths[np.argsort(-logits[paths])].astype(np.int64)
            g=_softmax_small(logits[paths]/ROUTE_TEMP)
        ix,v=self._selected_route(feat,paths); s=v@self.W[ai,ix,:]
        local_scores=[]
        for p in paths:
            li=feat['path_ix'][int(p)].astype(np.int64); lv=feat['path_vals'][int(p)].copy()
            lv=lv/max(float(np.linalg.norm(lv)),1e-12)
            local_scores.append(lv@self.W[ai,li,:])
        return {'arm':arm,'x':x,'paths':paths,'ix':ix,'v':v,'slow_scores':s,'g':g,
                'local_scores':np.stack(local_scores)}

    def route_all(self,c,event_index): return {a:self.route(a,c,event_index) for a in self.arms}

    def write(self,arm,packet,y):
        ai=self.ai[arm]; ix=packet['ix']; v=packet['v']; block=self.W[ai,ix,:]; s=packet['slow_scores']; vv=float(v@v)
        if vv>1e-15:
            e=-s.copy(); e[int(y)]+=1.; self.W[ai,ix,:]=block+SLOW_RATE*np.outer(v/vv,e); self.updates[ai]+=1
            if packet['paths'] is not None:
                for p in packet['paths']: self.path_write_counts[ai,int(p)]+=1

    def _q_from_packet(self,arm,packet,y,event_index):
        g=np.asarray(packet['g'],float)
        if arm=='INPUT-LEARNED': q=g.copy()
        elif arm in PREDICTIVE_ARMS:
            probs=psoft_batch(packet['local_scores']); r=np.maximum(probs[:,int(y)],1e-300)**RESP_BETA
            q=g*r; q=q/max(float(q.sum()),1e-300)
        else: return None,None
        original=q.copy()
        if arm=='SHUFFLED-FEEDBACK':
            digest=hashlib.sha256(f'{self.seed}:v46shuffle:{event_index}'.encode()).digest()[:8]
            rg=np.random.default_rng(int.from_bytes(digest,'little')); q=q[rg.permutation(len(q))]
            self.shuffle_multiset_max_error=max(self.shuffle_multiset_max_error,float(np.max(np.abs(np.sort(q)-np.sort(original)))))
        return q,original

    def post_event(self,arm,packet,y,event_index):
        if packet['paths'] is None:return
        ai=self.ai[arm]; paths=np.asarray(packet['paths'],dtype=np.int64); self.route_events[ai]+=1
        self.selection_counts[ai,paths]+=1
        if arm in HOMEOSTATIC_ARMS:
            ind=np.zeros(PATHWAYS); ind[paths]=1.; self.usage[ai]=(1-USAGE_RHO)*self.usage[ai]+USAGE_RHO*ind
        g=packet['g']
        if g is not None:
            h=-float(np.sum(np.where(g>0,g*np.log(g),0.))); self.prior_entropy_sum[ai]+=h; self.prior_entropy_n[ai]+=1
        if arm not in LEARNED_PROTO_ARMS:return
        q,_orig=self._q_from_packet(arm,packet,y,event_index)
        h=-float(np.sum(np.where(q>0,q*np.log(q),0.))); self.resp_entropy_sum[ai]+=h; self.resp_entropy_n[ai]+=1
        x=packet['x']
        for j,p in enumerate(paths):
            alpha=PROTO_ETA*float(q[j]); c=(1-alpha)*self.prototypes[ai,int(p)]+alpha*x
            self.prototypes[ai,int(p)]=c/max(float(np.linalg.norm(c)),1e-12)

    def scores_readonly(self,arm,c,event_index=0): return self.route(arm,c,event_index,read_only=True)['slow_scores']
    def paths_readonly(self,arm,c,event_index=0):
        q=self.route(arm,c,event_index,read_only=True); return None if q['paths'] is None else tuple(map(int,q['paths']))

    def routing_health(self,arm):
        ai=self.ai[arm]; n=int(self.route_events[ai]); counts=self.selection_counts[ai].astype(float)
        if n<=0:return {'arm':arm,'route_events':0,'n_eff':None,'min_selection_rate':None,'max_selection_rate':None}
        rates=counts/n; total=float(counts.sum()); pi=counts/total if total>0 else np.full(PATHWAYS,1/PATHWAYS)
        neff=math.exp(-float(np.sum(np.where(pi>0,pi*np.log(pi),0.))))
        return {'arm':arm,'route_events':n,'n_eff':neff,'min_selection_rate':float(rates.min()),
                'max_selection_rate':float(rates.max()),'selection_rates':rates.tolist(),
                'path_write_counts':self.path_write_counts[ai].astype(int).tolist()}

    def prototype_rows(self,arm,checkpoint):
        ai=self.ai[arm]; rows=[]
        for p in range(PATHWAYS):
            for q in range(p,PATHWAYS):
                rows.append({'arm':arm,'checkpoint':checkpoint,'path_i':p,'path_j':q,
                             'cosine':float(self.prototypes[ai,p]@self.prototypes[ai,q])})
        return rows

    def state_bytes(self,arm):
        ai=self.ai[arm]
        # Charge each deployable arm its own copy of every fixed/learned slow component.
        return int(self.W[ai].nbytes+self.contacts.nbytes+self.proj.nbytes+self.U.nbytes+
                   self.path_blocks.nbytes+self.prototypes[ai].nbytes+self.usage[ai].nbytes+
                   self.selection_counts[ai].nbytes+self.path_write_counts[ai].nbytes+256)

    def state_hash(self):
        h=hashlib.sha256(); h.update(self.W.tobytes()); h.update(self.contacts.tobytes()); h.update(self.proj.tobytes())
        h.update(self.path_blocks.tobytes()); h.update(self.prototypes.tobytes()); h.update(self.usage.tobytes())
        h.update(self.selection_counts.tobytes()); h.update(self.path_write_counts.tobytes()); h.update(self.updates.tobytes())
        return h.hexdigest()

# --------------------------- online metrics / probes ------------------------
@dataclass
class Agg:
    n:int=0; loss_sum:float=0.; correct:int=0
    def add_prob(self,p,y):
        self.n+=1; self.loss_sum+=-math.log2(max(float(p[int(y)]),1e-300)); self.correct+=int(int(np.argmax(p))==int(y))
    def result(self):return {'n':self.n,'bpb':self.loss_sum/self.n if self.n else None,'accuracy':self.correct/self.n if self.n else None}

def target_for_probe(stream,current_targets,i):return int(current_targets[int(i)])
def contexts_for_ids(stream,ids,wrappers,current_targets):
    return [(V45.surface_context(stream['keys'][i],w),target_for_probe(stream,current_targets,i),int(i),int(w)) for i in ids for w in wrappers]

def probe_arms(system,fast,contexts,event_index=0):
    out={a:Agg() for a in ARMS}; before=system.state_hash()
    for c,y,_i,_w in contexts:
        pf=psoft(fast.scores(c,count_ops=False))
        for arm in ARMS: out[arm].add_prob(.5*pf+.5*psoft(system.scores_readonly(arm,c,event_index)),y)
    if system.state_hash()!=before: raise AssertionError('probe mutated pathway system')
    return {a:g.result() for a,g in out.items()}

def probe_checkpoint(stream,current_targets,cp,system,fast,event_index):
    wi=ord(cp['wave'])-65; count=stream['keys_per_wave']; rows=[]; upto=min(len(stream['keys']),(wi+1)*count)
    for cohort in range(wi+1):
        ids=list(range(cohort*count,min((cohort+1)*count,len(stream['keys']))))
        tr=contexts_for_ids(stream,ids,V45.TRAIN_WRAPPERS,current_targets); he=contexts_for_ids(stream,ids,V45.HELDOUT_WRAPPERS,current_targets)
        qtr=probe_arms(system,fast,tr,event_index); qhe=probe_arms(system,fast,he,event_index)
        for arm in ARMS:
            rows.append({'checkpoint':cp['name'],'wave':cp['wave'],'cohort':chr(65+cohort),'arm':arm,
                         'trained_accuracy':qtr[arm]['accuracy'],'trained_bpb':qtr[arm]['bpb'],
                         'heldout_accuracy':qhe[arm]['accuracy'],'heldout_bpb':qhe[arm]['bpb'],'denominator_fraction':1.})
    all_he=contexts_for_ids(stream,list(range(upto)),V45.HELDOUT_WRAPPERS,current_targets); qall=probe_arms(system,fast,all_he,event_index)
    for arm in ARMS:
        rows.append({'checkpoint':cp['name'],'wave':cp['wave'],'cohort':'ALL','arm':arm,
                     'trained_accuracy':None,'trained_bpb':None,'heldout_accuracy':qall[arm]['accuracy'],
                     'heldout_bpb':qall[arm]['bpb'],'denominator_fraction':1.})
    return rows

def probe_bank(stream,current_targets,wave_index,current_id,seed):
    count=stream['keys_per_wave']; prior=list(range(max(0,wave_index*count)))
    if not prior:return []
    def h(i):return hashlib.sha256(f'v46probe:{seed}:{wave_index}:{i}'.encode()).digest()
    chosen=sorted(prior,key=h)[:min(INTERFERENCE_PROBES,len(prior))]
    if current_id in prior and current_id not in chosen:
        if chosen:chosen[-1]=current_id
        else:chosen=[current_id]
    out=[]
    for i in chosen:
        w=4 if i%2==0 else 5; out.append((V45.surface_context(stream['keys'][i],w),int(current_targets[i]),int(i),int(w)))
    return out

def _losses_for_arm(system,fast,arm,contexts,event_index):
    vals=[]
    for c,y,_i,_w in contexts:
        p=.5*psoft(fast.scores(c,count_ops=False))+.5*psoft(system.scores_readonly(arm,c,event_index))
        vals.append(-math.log2(max(float(p[int(y)]),1e-300)))
    return vals

def audit_before(system,fast,contexts,event_index):return {a:_losses_for_arm(system,fast,a,contexts,event_index) for a in ARMS}
def finish_interference(system,fast,contexts,before,event_meta,event_index):
    rows=[]; cid=int(event_meta['key_id']); cy=int(event_meta['y'])
    for arm in ARMS:
        after=_losses_for_arm(system,fast,arm,contexts,event_index); pre=before[arm]
        groups={'all':[],'same_identity_alt':[],'same_outcome_diff_identity':[],'different_outcome_diff_identity':[]}
        for j,(_c,py,pid,_w) in enumerate(contexts):
            d=float(after[j]-pre[j]); groups['all'].append(d)
            if pid==cid:groups['same_identity_alt'].append(d)
            elif int(py)==cy:groups['same_outcome_diff_identity'].append(d)
            else:groups['different_outcome_diff_identity'].append(d)
        for cat,vals in groups.items():
            rows.append({'event_index':int(event_index),'arm':arm,'category':cat,'n_probes':len(vals),
                         'mean_delta_bpb':float(np.mean(vals)) if vals else None,'wave':event_meta['wave'],
                         'pos':event_meta['pos'],'kind':event_meta['kind'],'key_id':cid,'outcome':cy})
    return rows

def pathway_overlap(system,stream,current_targets,event_index):
    rows=[]
    routed=ROUTED_ARMS
    for arm in routed:
        same=[]; same_out=[]; diff_out=[]
        # same identity, trained wrapper 0 versus unseen 4 and 5
        for i,k in enumerate(stream['keys']):
            a=system.paths_readonly(arm,V45.surface_context(k,0),event_index)
            for w in V45.HELDOUT_WRAPPERS:
                b=system.paths_readonly(arm,V45.surface_context(k,w),event_index); same.append(_jaccard(a,b))
        by=collections.defaultdict(list)
        for i,y in enumerate(current_targets):by[int(y)].append(i)
        for members in by.values():
            for a_i,b_i in zip(members[::2],members[1::2]):
                a=system.paths_readonly(arm,V45.surface_context(stream['keys'][a_i],4),event_index)
                b=system.paths_readonly(arm,V45.surface_context(stream['keys'][b_i],4),event_index); same_out.append(_jaccard(a,b))
        ids=list(range(len(stream['keys']))); rng=np.random.default_rng(stream['seed']+460088)
        rng.shuffle(ids)
        for a_i,b_i in zip(ids[::2],ids[1::2]):
            if int(current_targets[a_i])==int(current_targets[b_i]):continue
            a=system.paths_readonly(arm,V45.surface_context(stream['keys'][a_i],5),event_index)
            b=system.paths_readonly(arm,V45.surface_context(stream['keys'][b_i],5),event_index); diff_out.append(_jaccard(a,b))
        rows.append({'arm':arm,'same_identity_jaccard':float(np.mean(same)) if same else None,
                     'different_identity_same_outcome_jaccard':float(np.mean(same_out)) if same_out else None,
                     'different_identity_different_outcome_jaccard':float(np.mean(diff_out)) if diff_out else None,
                     'same_minus_diffout':(float(np.mean(same))-float(np.mean(diff_out))) if same and diff_out else None})
    return rows

# ------------------------------ runtime ------------------------------------
@dataclass
class RuntimeState:
    record_index:int; event_index:int; history:bytearray; current_targets:np.ndarray
    base_enc:object; base:object; fast:object; system:PathwaySystem; groups:dict
    checkpoint_rows:list=field(default_factory=list); revision_rows:list=field(default_factory=list)
    interference_rows:list=field(default_factory=list); prototype_rows:list=field(default_factory=list)
    peak_rss_bytes:int=0

def new_runtime(seed,stream,U_pair):
    return RuntimeState(record_index=0,event_index=0,history=bytearray(),current_targets=np.array(stream['labels'],dtype=np.int64),
        base_enc=V39.Encoder(seed,'last_fd'),base=V39.Learner('full'),
        fast=V45.CAND_A.SparseLayer(seed,V45.FAST_UNITS,V45.FAST_K,V45.FAST_CONTACTS,V45.FAST_RATE),
        system=PathwaySystem(seed,U_pair),groups={a:{'whole':Agg(),'target':Agg(),'nontarget':Agg()} for a in ARMS},
        peak_rss_bytes=current_rss_bytes())

def clear_transient(state):
    if hasattr(state.fast,'_enc_cache'):state.fast._enc_cache={}
    state.system.clear_transient()

def runtime_hash(state):
    h=hashlib.sha256(); h.update(state.system.state_hash().encode()); h.update(state.fast.output.tobytes())
    h.update(state.base.state_hash().encode() if hasattr(state.base,'state_hash') else repr(state.base).encode())
    h.update(bytes(state.history)); h.update(state.current_targets.tobytes()); h.update(str(state.record_index).encode()); h.update(str(state.event_index).encode())
    return h.hexdigest()

def persistent_identity(seed,load,stream_sha,dev_sha,smoke=False):
    return sha_json({'version':VERSION,'source':source_sha(),'design':DESIGN_SHA256,'seed':int(seed),'load':int(load),
                     'stream':stream_sha,'development':dev_sha,'smoke':bool(smoke),'numpy':np.__version__,
                     'params':{'pathways':PATHWAYS,'routes':ROUTES_PER_EVENT,'units_per_route':UNITS_PER_ROUTE,
                               'usage_rho':USAGE_RHO,'lambda':HOMEOSTASIS_LAMBDA,'temp':ROUTE_TEMP,
                               'proto_eta':PROTO_ETA,'beta':RESP_BETA,'slow_rate':SLOW_RATE}})

def save_checkpoint(path,identity,state):clear_transient(state); atomic_pickle(path,{'identity':identity,'state':state})
def load_checkpoint(path,identity):
    x=load_pickle(path)
    if x.get('identity')!=identity:raise RuntimeError('checkpoint identity mismatch')
    return x['state']

def run_persistent_job(seed,load,out_dir,smoke=False,stop_after_records=None,arm_order=ARMS):
    out_dir=Path(out_dir); jobs=out_dir/'jobs'; jobs.mkdir(parents=True,exist_ok=True)
    md,U_pair,dev_keys=load_development(out_dir,seed,smoke)
    stream=V45.make_persistent_stream(seed,load,exclude_keys=dev_keys,smoke=smoke)
    identity=persistent_identity(seed,load,stream['raw_sha256'],md['npz_sha256'],smoke)
    result_path=jobs/f'L{load}_S{seed}.json.gz'; checkpoint=jobs/f'L{load}_S{seed}.checkpoint.pkl'
    if result_path.exists() and arm_order==ARMS:
        try:
            x=load_gzip_json(result_path)
            if x.get('identity')==identity:return {'status':'reused','result':x['result']}
        except Exception:pass
    sched=build_base_schedule(seed,stream); sampled=sampled_events(seed,sched['ordinary'])
    if checkpoint.exists() and arm_order==ARMS: state=load_checkpoint(checkpoint,identity)
    else:
        state=new_runtime(seed,stream,U_pair)
        if arm_order!=ARMS: state.system=PathwaySystem(seed,U_pair,arm_order=arm_order)
    cpmap=collections.defaultdict(list)
    for cp in stream['checkpoints']:cpmap[cp['record_count']].append(cp)
    t0=time.time()
    for ri in range(state.record_index,len(stream['rows'])):
        row=stream['rows'][ri]
        if row['kind']=='revision':state.current_targets[int(row['key_id'])]=int(row['target'])
        wave_index=max(0,ord(row['wave'])-65)
        for pos,y in enumerate(row['raw']):
            idx=state.event_index; z,b=state.base_enc.encode(state.history); sb=state.base.scores(z,b); fs=state.fast.scores(state.history); pf=psoft(fs)
            full=len(state.history)>=12; c=bytes(state.history)[-12:] if full else None
            routes=state.system.route_all(c,idx) if full else None
            for arm in ARMS:
                ss=routes[arm]['slow_scores'] if full else np.zeros(OUTPUTS)
                p=.5*pf+.5*psoft(ss); state.groups[arm]['whole'].add_prob(p,y); state.groups[arm]['target' if pos==12 else 'nontarget'].add_prob(p,y)
            base_miss=(int(np.argmax(sb))!=int(y)) and full
            if base_miss!=(idx in sched['ordinary']):raise AssertionError('BASE-miss schedule drift')
            contexts=[]; before=None
            if base_miss and idx in sampled:
                contexts=probe_bank(stream,state.current_targets,wave_index,int(row['key_id']),seed)
                if contexts:before=audit_before(state.system,state.fast,contexts,idx)
            if base_miss:
                for arm in ARMS:state.system.write(arm,routes[arm],int(y))
            if before is not None:state.interference_rows.extend(finish_interference(state.system,state.fast,contexts,before,sched['event_meta'][idx],idx))
            if full:
                for arm in ARMS:state.system.post_event(arm,routes[arm],int(y),idx)
            state.base.observe(z,b,int(y)); state.fast.write(state.history,int(y)); state.history.append(int(y))
            if len(state.history)>12:del state.history[:-12]
            state.event_index+=1
        state.record_index=ri+1; state.peak_rss_bytes=max(state.peak_rss_bytes,current_rss_bytes())
        for cp in cpmap.get(state.record_index,[]):
            newrows=probe_checkpoint(stream,state.current_targets,cp,state.system,state.fast,state.event_index); state.checkpoint_rows.extend(newrows)
            for arm in ARMS:state.prototype_rows.extend(state.system.prototype_rows(arm,cp['name']))
            if cp['type']=='revision':
                for r in newrows:
                    if r['cohort']=='A':state.revision_rows.append(dict(r,revision_exposure=cp['exposure']))
        if state.record_index%64==0 or cpmap.get(state.record_index):
            if arm_order==ARMS:save_checkpoint(checkpoint,identity,state)
        if stop_after_records is not None and state.record_index>=stop_after_records:
            if arm_order==ARMS:save_checkpoint(checkpoint,identity,state)
            return {'status':'partial','record_index':state.record_index,'identity':identity}

    final=[r for r in state.checkpoint_rows if r['checkpoint']=='after_D']; terminal=[]
    for arm in ARMS:
        allrow=next(r for r in final if r['arm']==arm and r['cohort']=='ALL'); drow=next(r for r in final if r['arm']==arm and r['cohort']=='D')
        g={k:v.result() for k,v in state.groups[arm].items()}
        terminal.append({'seed':seed,'load':load,'arm':arm,'whole_bpb':g['whole']['bpb'],'whole_accuracy':g['whole']['accuracy'],
                         'target_bpb':g['target']['bpb'],'target_accuracy':g['target']['accuracy'],'nontarget_bpb':g['nontarget']['bpb'],
                         'D_after_D_trained_accuracy':drow['trained_accuracy'],'D_after_D_trained_bpb':drow['trained_bpb'],
                         'heldout_after_D_accuracy':allrow['heldout_accuracy'],'heldout_after_D_bpb':allrow['heldout_bpb']})
    isum=[]; by=collections.defaultdict(list)
    for x in state.interference_rows:
        if x['mean_delta_bpb'] is not None:by[(x['arm'],x['category'])].append(float(x['mean_delta_bpb']))
    for (arm,cat),vals in by.items():isum.append({'seed':seed,'load':load,'arm':arm,'category':cat,'n_events':len(vals),'mean_delta_bpb':float(np.mean(vals))})
    usage=[]; resp=[]
    for arm in ARMS:
        rh=state.system.routing_health(arm); rh.update(seed=seed,load=load); usage.append(rh)
        ai=state.system.ai[arm]
        resp.append({'seed':seed,'load':load,'arm':arm,'n':int(state.system.resp_entropy_n[ai]),
                     'mean_responsibility_entropy':float(state.system.resp_entropy_sum[ai]/max(1,state.system.resp_entropy_n[ai])),
                     'mean_prior_entropy':float(state.system.prior_entropy_sum[ai]/max(1,state.system.prior_entropy_n[ai])),
                     'prototype_move_mean':float(np.mean(np.linalg.norm(state.system.prototypes[ai]-state.system.initial_prototypes,axis=1)))})
    overlap=pathway_overlap(state.system,stream,state.current_targets,state.event_index)
    for r in overlap:r.update(seed=seed,load=load)
    costs=[]
    for arm in ARMS:
        costs.append({'seed':seed,'load':load,'arm':arm,'slow_semantic_bytes':state.system.state_bytes(arm),
                      'slow_matrix_bytes':int(state.system.W[state.system.ai[arm]].nbytes),'projection_bytes':int(state.system.contacts.nbytes+state.system.proj.nbytes),
                      'representation_bytes':int(U_pair.nbytes),'routing_state_bytes':int(state.system.path_blocks.nbytes+state.system.prototypes[state.system.ai[arm]].nbytes+state.system.usage[state.system.ai[arm]].nbytes),
                      'writes':int(state.system.updates[state.system.ai[arm]])})
    result={'seed':seed,'load':load,'identity':identity,'stream_sha256':stream['raw_sha256'],'development_sha256':md['npz_sha256'],
            'terminal':terminal,'checkpoints':state.checkpoint_rows,'revision':state.revision_rows,'state_costs':costs,
            'routing_health':usage,'pathway_overlap':overlap,'prototype_rows':state.prototype_rows,'responsibility_summary':resp,
            'interference_events':state.interference_rows,'interference_summary':isum,
            'sample_budget':{'development_raw_bytes':md['dev_raw_byte_budget'],'persistent_raw_bytes':len(stream['raw']),'persistent_records':len(stream['rows'])},
            'schedule':{'ordinary_count':len(sched['ordinary']),'ordinary_hash':sched['ordinary_hash']},
            'firewall':{'no_permanent_slots':True,'common_base_miss_schedule':True,'pair_frozen':True,'weights_equal_shape':True,
                        'active_slow_units_per_write':SLOW_K,'shuffled_multiset_max_error':state.system.shuffle_multiset_max_error},
            'final_state_hash':runtime_hash(state),'peak_rss_bytes':state.peak_rss_bytes,'elapsed_seconds':time.time()-t0}
    if arm_order==ARMS:
        atomic_gzip_json(result_path,{'identity':identity,'result':result})
        if checkpoint.exists():checkpoint.unlink()
    return {'status':'new','result':result}

def run_persistent_worker(task):
    seed,load,out_dir,smoke=task; return run_persistent_job(int(seed),int(load),Path(out_dir),bool(smoke))

# ------------------------- engineering / static tests -----------------------
def static_self_test():
    checks={}
    assert PATHWAYS*UNITS_PER_PATH==SLOW_UNITS and ROUTES_PER_EVENT*UNITS_PER_ROUTE==SLOW_K
    checks['resource_partition_arithmetic']=True
    seed=ENGINEERING_SEEDS[0]; dev=V45.learn_development(seed,True); U=dev['U_PAIR']; sys1=PathwaySystem(seed,U)
    flat=np.sort(sys1.path_blocks.ravel()); assert np.array_equal(flat,np.arange(SLOW_UNITS)); checks['path_partition_complete']=True
    c=V45.surface_context(dev['dev_identity_keys'][0],0)
    for arm in ARMS:
        p=sys1.route(arm,c,17); assert len(p['ix'])==SLOW_K
        if p['paths'] is not None:assert len(set(map(int,p['paths'])))==ROUTES_PER_EVENT
    checks['exactly_51_active_units']=True
    # GLOBAL encoding must match V45 PAIR encoding exactly.
    Udict={'U_RAW':np.zeros_like(U),'U_PAIR':U,'U_SHUFFLED':U,'U_RANDOM':U}
    old=V45.SlowSystem(seed,Udict); ix0,v0=old.encode_rep('PAIR',c); p=sys1.route('GLOBAL-PAIR',c,0)
    assert np.array_equal(ix0,p['ix']) and np.allclose(v0,p['v'],atol=1e-12); checks['global_encoding_matches_v45']=True
    # One write must match V45's inherited delta semantics.
    y=97; old.write('PAIR-ORDINARY',c,y,(ix0,v0)); sys1.write('GLOBAL-PAIR',p,y)
    assert np.allclose(old.W[old.arm_index['PAIR-ORDINARY']],sys1.W[sys1.ai['GLOBAL-PAIR']],atol=1e-12); checks['global_write_matches_v45']=True
    # Shuffled control preserves responsibility multiset.
    sh=sys1.route('SHUFFLED-FEEDBACK',c,123); q,orig=sys1._q_from_packet('SHUFFLED-FEEDBACK',sh,y,123)
    assert np.allclose(np.sort(q),np.sort(orig)); checks['shuffle_preserves_q_multiset']=True
    # Read-only probe cannot mutate state.
    h=sys1.state_hash(); _=sys1.scores_readonly('PRED-RESP',c,5); assert h==sys1.state_hash(); checks['readonly_route_pure']=True
    # Arm-order invariance over a short deterministic sequence.
    a=PathwaySystem(seed,U,ARMS); b=PathwaySystem(seed,U,tuple(reversed(ARMS)))
    seq=[(V45.surface_context(dev['dev_identity_keys'][i%len(dev['dev_identity_keys'])],i%6),(31*i+7)%256) for i in range(24)]
    for ei,(cc,yy) in enumerate(seq):
        ra={arm:a.route(arm,cc,ei) for arm in ARMS}; rb={arm:b.route(arm,cc,ei) for arm in ARMS}
        for arm in ARMS:
            a.write(arm,ra[arm],yy); b.write(arm,rb[arm],yy); a.post_event(arm,ra[arm],yy,ei); b.post_event(arm,rb[arm],yy,ei)
    for arm in ARMS:
        assert np.allclose(a.W[a.ai[arm]],b.W[b.ai[arm]])
        assert np.allclose(a.prototypes[a.ai[arm]],b.prototypes[b.ai[arm]])
    checks['arm_order_invariant']=True
    assert max(sys1.state_bytes(a) for a in ARMS)<=STATE_CAP_BYTES; checks['state_cap_static']=True
    return checks

def engineering_check(out_dir,workers=2):
    out_dir=Path(out_dir); edir=out_dir/'engineering'; edir.mkdir(parents=True,exist_ok=True)
    checks={'static':static_self_test()}
    # deterministic development on an engineering seed
    d1=V45.learn_development(ENGINEERING_SEEDS[0],True); d2=V45.learn_development(ENGINEERING_SEEDS[0],True)
    checks['development_deterministic']=bool(np.array_equal(d1['U_PAIR'],d2['U_PAIR']))
    if not checks['development_deterministic']:raise AssertionError('development nondeterministic')
    # Smoke uninterrupted versus forced checkpoint/resume in disjoint directories.
    full=edir/'full'; resume=edir/'resume'
    for d in (full,resume):d.mkdir(parents=True,exist_ok=True)
    for d in (full,resume):run_development_worker((ENGINEERING_SEEDS[0],str(d),True))
    a=run_persistent_job(ENGINEERING_SEEDS[0],64,full,True)['result']
    part=run_persistent_job(ENGINEERING_SEEDS[0],64,resume,True,stop_after_records=9)
    assert part['status']=='partial'; b=run_persistent_job(ENGINEERING_SEEDS[0],64,resume,True)['result']
    checks['resume_bit_identical']=bool(a['final_state_hash']==b['final_state_hash'] and a['terminal']==b['terminal'])
    if not checks['resume_bit_identical']:raise AssertionError('resume mismatch')
    # Spawn determinism: two seeds in 2-worker and 4-worker directories.
    sp2=edir/'spawn2'; sp4=edir/'spawn4'
    seeds=ENGINEERING_SEEDS[1:3]
    for d in (sp2,sp4):
        d.mkdir(parents=True,exist_ok=True)
        for s in seeds:run_development_worker((s,str(d),True))
    t2=[(s,64,str(sp2),True) for s in seeds]; t4=[(s,64,str(sp4),True) for s in seeds]
    r2=run_parallel(t2,run_persistent_worker,min(2,workers)); r4=run_parallel(t4,run_persistent_worker,min(4,max(workers,2)))
    h2=sorted((x['result']['seed'],x['result']['final_state_hash']) for x in r2); h4=sorted((x['result']['seed'],x['result']['final_state_hash']) for x in r4)
    checks['spawn_deterministic']=bool(h2==h4)
    if not checks['spawn_deterministic']:raise AssertionError('spawn mismatch')
    # Firewall and route-health sanity.
    checks['no_slots']=all(x['result']['firewall']['no_permanent_slots'] for x in r2)
    checks['shuffle_multiset_error_max']=max(x['result']['firewall']['shuffled_multiset_max_error'] for x in r2)
    atomic_json(out_dir/'RESUME_AUDIT.json',checks)
    atomic_json(out_dir/'FIREWALL_AUDIT.json',{'no_permanent_slots':checks['no_slots'],'design_sha256':DESIGN_SHA256,
                                             'science_seeds_disjoint':not bool(set(SCIENCE_SEEDS)&set(ENGINEERING_SEEDS))})
    return checks

# ------------------------------ aggregation --------------------------------
def flatten_results(out_dir,seeds,loads):
    out=[]
    for load in loads:
        for seed in seeds:
            p=Path(out_dir)/'jobs'/f'L{load}_S{seed}.json.gz'
            if not p.exists():continue
            x=load_gzip_json(p); out.append(x['result'])
    return out

def contrast_interference(isum,left,right,category,load=PRIMARY_LOAD):
    by=collections.defaultdict(dict)
    for r in isum:
        if int(r['load'])==int(load) and r['category']==category:by[int(r['seed'])][r['arm']]=r['mean_delta_bpb']
    vals=[a[left]-a[right] for a in by.values() if left in a and right in a]
    return interval(vals)

def aggregate(out_dir,seeds):
    out_dir=Path(out_dir); results=flatten_results(out_dir,seeds,[PRIMARY_LOAD,SECONDARY_LOAD])
    terminal=[]; checkpoints=[]; revision=[]; costs=[]; routing=[]; overlap=[]; protos=[]; resp=[]; ievents=[]; isum=[]; budgets=[]
    for r in results:
        terminal+=r['terminal']
        checkpoints += [dict(x,seed=r['seed'],load=r['load']) for x in r['checkpoints']]
        revision += [dict(x,seed=r['seed'],load=r['load']) for x in r['revision']]
        costs+=r['state_costs']; routing+=r['routing_health']; overlap+=r['pathway_overlap']
        protos += [dict(x,seed=r['seed'],load=r['load']) for x in r['prototype_rows']]
        resp+=r['responsibility_summary']
        ievents += [dict(x,seed=r['seed'],load=r['load']) for x in r['interference_events']]
        isum+=r['interference_summary']; budgets.append(dict(seed=r['seed'],load=r['load'],**r['sample_budget']))
    devrows=[]
    for s in seeds:
        p=out_dir/'development'/f'S{s}.json'
        if p.exists():
            m=json.loads(p.read_text()); devrows.append({'seed':s,'pair_updates':m['pair_updates'],'false_pair_rate':m['false_pair_rate'],'rank_pair':m['rank_pair'],'dev_records':m['dev_records'],'dev_raw_byte_budget':m['dev_raw_byte_budget']})
    # G0 implementation/firewall.
    g0=bool(results) and all(r['firewall']['no_permanent_slots'] and r['firewall']['common_base_miss_schedule'] and r['firewall']['pair_frozen'] and r['firewall']['active_slow_units_per_write']==SLOW_K and r['firewall']['shuffled_multiset_max_error']<1e-12 for r in results)
    # G1 development.
    pair_updates=[r['pair_updates'] for r in devrows]; false=[r['false_pair_rate'] for r in devrows if r['false_pair_rate'] is not None]
    g1_stats={'pair_updates':interval(pair_updates),'false_pair_rate':interval(false),'all_rank20':all(r['rank_pair']==20 for r in devrows)}
    # Geometry from U only, use V45 helper on regenerated stream per seed at primary.
    geom=[]
    for s in seeds:
        try:
            md,U,keys=load_development(out_dir,s,False); st=V45.make_persistent_stream(s,PRIMARY_LOAD,exclude_keys=keys,smoke=False)
            raw=[]; pair=[]
            for k in st['keys']:
                z0=V45.clean_rep(V45.surface_context(k,0),np.zeros_like(U)); zp0=V45.clean_rep(V45.surface_context(k,0),U)
                for w in V45.HELDOUT_WRAPPERS:
                    raw.append(float(z0@V45.clean_rep(V45.surface_context(k,w),np.zeros_like(U))))
                    pair.append(float(zp0@V45.clean_rep(V45.surface_context(k,w),U)))
            labels=np.asarray(st['labels']); by=collections.defaultdict(list)
            for i,y in enumerate(labels):by[int(y)].append(i)
            dr=[]; dp=[]
            for members in by.values():
                for a,b in zip(members[::2],members[1::2]):
                    dr.append(float(V45.clean_rep(V45.surface_context(st['keys'][a],4),np.zeros_like(U))@V45.clean_rep(V45.surface_context(st['keys'][b],4),np.zeros_like(U))))
                    dp.append(float(V45.clean_rep(V45.surface_context(st['keys'][a],4),U)@V45.clean_rep(V45.surface_context(st['keys'][b],4),U)))
            geom.append({'seed':s,'raw_margin':float(np.mean(raw)-np.mean(dr)),'pair_margin':float(np.mean(pair)-np.mean(dp)),'pair_minus_raw':float((np.mean(pair)-np.mean(dp))-(np.mean(raw)-np.mean(dr)))})
        except Exception:pass
    pairgeom=interval([g['pair_minus_raw'] for g in geom]); g1=bool(len(devrows)==len(seeds) and g1_stats['all_rank20'] and g1_stats['pair_updates']['mean']>=300 and g1_stats['false_pair_rate']['mean']<=.05 and pairgeom['mean']>=.08 and pairgeom['low']>0)
    # G2 routing health PRED at primary.
    pred_r=[r for r in routing if r['arm']=='PRED-RESP' and int(r['load'])==PRIMARY_LOAD]
    g2=bool(len(pred_r)==len(seeds) and all(r['n_eff'] is not None and r['n_eff']>=5 and r['min_selection_rate']>=.02 and r['max_selection_rate']<=.65 and all(int(x)>0 for x in r['path_write_counts']) for r in pred_r))
    # G3 acquisition.
    def levels(arm,key,load=PRIMARY_LOAD):return [r[key] for r in terminal if r['arm']==arm and int(r['load'])==load]
    glob_acc=levels('GLOBAL-PAIR','D_after_D_trained_accuracy'); pred_acc=levels('PRED-RESP','D_after_D_trained_accuracy')
    g3=bool(len(glob_acc)==len(seeds) and len(pred_acc)==len(seeds) and np.mean(glob_acc)>=.90 and np.mean(pred_acc)>=.90 and min(glob_acc)>=.80 and min(pred_acc)>=.80)
    # G4 interference.
    dI=contrast_interference(isum,'PRED-RESP','GLOBAL-PAIR','different_outcome_diff_identity')
    dT=contrast_interference(isum,'PRED-RESP','GLOBAL-PAIR','same_identity_alt')
    g4=bool(dI['mean'] is not None and dI['mean']<=-.00075 and dI['high']<0 and dT['high'] is not None and dT['high']<=.05)
    # G5 persistent.
    dL=paired(terminal,'PRED-RESP','GLOBAL-PAIR','heldout_after_D_bpb'); g5=bool(dL['mean'] is not None and dL['mean']<=-.10 and dL['high']<0)
    # G6 specificity: control - PRED >= .05 => paired(control,pred) positive.
    controls=('INPUT-LEARNED','FROZEN-ROUTE','HASH-ROUTE','SHUFFLED-FEEDBACK'); spec={c:paired(terminal,c,'PRED-RESP','heldout_after_D_bpb') for c in controls}
    spec_pass={c:bool(v['mean'] is not None and v['mean']>=.05 and v['low']>0) for c,v in spec.items()}; g6=all(spec_pass.values())
    # G7 safety.
    whole=paired(terminal,'PRED-RESP','GLOBAL-PAIR','whole_bpb')
    revp=[r for r in revision if int(r.get('revision_exposure',-1))==8 and r['arm']=='PRED-RESP']; revg=[r for r in revision if int(r.get('revision_exposure',-1))==8 and r['arm']=='GLOBAL-PAIR']
    byp={int(r.get('seed',-1)):r for r in revp}; byg={int(r.get('seed',-1)):r for r in revg}
    rev_acc=interval([byp[s]['trained_accuracy']-byg[s]['trained_accuracy'] for s in byp if s in byg]); rev_bpb=interval([byp[s]['trained_bpb']-byg[s]['trained_bpb'] for s in byp if s in byg])
    g7=bool(whole['mean'] is not None and whole['mean']<=.02 and whole['high']<=.04 and (rev_acc['mean'] is None or rev_acc['mean']>=-.05) and (rev_bpb['high'] is None or rev_bpb['high']<=.10))
    # G8 scaling.
    gain256=paired(terminal,'GLOBAL-PAIR','PRED-RESP','heldout_after_D_bpb',PRIMARY_LOAD)
    gain128=paired(terminal,'GLOBAL-PAIR','PRED-RESP','heldout_after_D_bpb',SECONDARY_LOAD)
    g8=bool(gain256['mean'] is not None and gain128['mean'] is not None and gain256['mean']>=.75*max(gain128['mean'],.05))
    # G9 state.
    dist=[r for r in costs if r['arm'] in ARMS]; g9=bool(dist and max(r['slow_semantic_bytes'] for r in dist)<=STATE_CAP_BYTES)
    for arm in ARMS:
        lv={int(r['load']):int(r['slow_semantic_bytes']) for r in dist if r['arm']==arm}
        if PRIMARY_LOAD in lv and SECONDARY_LOAD in lv and lv[PRIMARY_LOAD]!=lv[SECONDARY_LOAD]:g9=False
    # verdict ordered.
    if not g0:verdict='IMPLEMENTATION_INVALID'
    elif not g1:verdict='DEVELOPMENT_INVALID'
    elif not g2:verdict='ROUTING_COLLAPSE'
    elif not g3:verdict='INVALID_ACQUISITION'
    elif not g4:verdict='NO_SELECTIVE_INTERFERENCE_GAIN'
    elif not g5:verdict='INTERFERENCE_REDUCED_NO_PERSISTENT_GAIN'
    elif not g6:
        if not spec_pass['INPUT-LEARNED']:verdict='INPUT_CLUSTERING_SUFFICIENT'
        elif (not spec_pass['FROZEN-ROUTE']) or (not spec_pass['HASH-ROUTE']):verdict='STATIC_PARTITIONING_SUFFICIENT'
        elif not spec_pass['SHUFFLED-FEEDBACK']:verdict='FEEDBACK_SPECIFICITY_FAILED'
        else:verdict='SPECIFICITY_FAILED'
    elif not g7:verdict='PERSISTENCE_GAIN_WITH_SAFETY_COST'
    elif not g8:verdict='GAIN_COLLAPSES_WITH_LOAD'
    elif not g9:verdict='STATE_BUDGET_FAIL'
    else:verdict='QUALIFIED_LEARNED_PATHWAYS'
    gates={'G0_implementation':g0,'G1_development':g1,'G1_stats':g1_stats,'G1_pair_geometry':pairgeom,
           'G2_routing_health':g2,'G3_acquisition':g3,'G4_selective_interference':g4,'G4_pred_minus_global_diffout':dI,'G4_pred_minus_global_sameid':dT,
           'G5_persistent_gain':g5,'G5_pred_minus_global_heldout_bpb':dL,'G6_specificity':g6,'G6_controls_minus_pred':spec,'G6_pass_by_control':spec_pass,
           'G7_safety':g7,'G7_whole_bpb':whole,'G7_revision_accuracy':rev_acc,'G7_revision_bpb':rev_bpb,
           'G8_scaling':g8,'G8_gain256':gain256,'G8_gain128':gain128,'G9_bounded_state':g9,'verdict':verdict}
    # outputs
    write_csv(out_dir/'DEVELOPMENT_AUDIT.csv',devrows); write_csv(out_dir/'TERMINAL.csv',terminal); write_csv(out_dir/'CHECKPOINT_METRICS.csv.gz',checkpoints,True)
    # contrasts
    cons=[]
    for left,right in [('PRED-RESP','GLOBAL-PAIR')]+[(c,'PRED-RESP') for c in controls]:
        row={'left':left,'right':right,'load':PRIMARY_LOAD}
        for key in ('heldout_after_D_bpb','heldout_after_D_accuracy','D_after_D_trained_accuracy','whole_bpb'):
            st=paired(terminal,left,right,key); row.update({f'{key}_{k}':v for k,v in st.items()})
        cons.append(row)
    write_csv(out_dir/'PERSISTENCE_CONTRASTS.csv',cons); write_csv(out_dir/'ROUTING_HEALTH.csv',routing)
    usage=[]
    for r in routing:
        rates=r.get('selection_rates') or []
        for p,x in enumerate(rates):usage.append({'seed':r['seed'],'load':r['load'],'arm':r['arm'],'path':p,'selection_rate':x,'write_count':(r.get('path_write_counts') or [None]*PATHWAYS)[p]})
    write_csv(out_dir/'PATHWAY_USAGE.csv',usage); write_csv(out_dir/'PATHWAY_OVERLAP.csv',overlap); write_csv(out_dir/'PATHWAY_PROTOTYPES.csv.gz',protos,True)
    write_csv(out_dir/'RESPONSIBILITY_SUMMARY.csv',resp); write_csv(out_dir/'INTERFERENCE_SUMMARY.csv',isum); write_csv(out_dir/'INTERFERENCE_EVENTS.csv.gz',ievents,True)
    write_csv(out_dir/'REVISION.csv',revision); write_csv(out_dir/'STATE_COSTS.csv',costs); write_csv(out_dir/'SAMPLE_BUDGET.csv',budgets)
    atomic_json(out_dir/'GATES.json',gates)
    report={'verdict':verdict,'gates':gates,'n_results':len(results),'science_seeds':list(seeds),'loads':[PRIMARY_LOAD,SECONDARY_LOAD]}; atomic_json(out_dir/'REPORT.json',report)
    manifest={'version':VERSION,'source_sha256':source_sha(),'design_sha256':DESIGN_SHA256,'v45_embedded_sha256':sha_bytes(zlib.decompress(base64.b64decode(V45_PAYLOAD.encode()))),
              'science_seeds':list(seeds),'loads':[PRIMARY_LOAD,SECONDARY_LOAD],'numpy':np.__version__,'scipy':None if scipy is None else scipy.__version__,
              'platform':platform.platform(),'records':len(results),'verdict':verdict}; atomic_json(out_dir/'MANIFEST.json',manifest)
    (out_dir/'PROTOCOL.md').write_text(DESIGN_TEXT)
    lines=['# V46 results — Learned Overlapping Slow Pathways','',f'**Verdict:** `{verdict}`','',
           f'- G0 implementation: **{g0}**',f'- G1 development: **{g1}**',f'- G2 routing health: **{g2}**',f'- G3 acquisition: **{g3}**',
           f'- G4 selective interference: **{g4}**',f'- G5 persistent gain: **{g5}**',f'- G6 specificity: **{g6}**',f'- G7 safety: **{g7}**',f'- G8 scaling: **{g8}**',f'- G9 bounded state: **{g9}**','',
           '## Primary contrasts','',f"- `PRED-RESP - GLOBAL-PAIR` heldout bpb: {dL['mean']} [{dL['low']}, {dL['high']}]",f"- harmful diff-outcome interference: {dI['mean']} [{dI['low']}, {dI['high']}]",f"- same-identity transfer change: {dT['mean']} [{dT['low']}, {dT['high']}]",'',
           'No permanent-slot arm is present in V46.']
    (out_dir/'SUMMARY.md').write_text('\n'.join(lines)+'\n')
    return gates

def package_upload(out_dir):
    out_dir=Path(out_dir); target=out_dir/'v46_results_upload.zip'
    include=['MANIFEST.json','PROTOCOL.md','GATES.json','SUMMARY.md','REPORT.json','DEVELOPMENT_AUDIT.csv','TERMINAL.csv','CHECKPOINT_METRICS.csv.gz','PERSISTENCE_CONTRASTS.csv','ROUTING_HEALTH.csv','PATHWAY_USAGE.csv','PATHWAY_OVERLAP.csv','PATHWAY_PROTOTYPES.csv.gz','RESPONSIBILITY_SUMMARY.csv','INTERFERENCE_SUMMARY.csv','INTERFERENCE_EVENTS.csv.gz','REVISION.csv','STATE_COSTS.csv','SAMPLE_BUDGET.csv','RESUME_AUDIT.json','FIREWALL_AUDIT.json']
    with zipfile.ZipFile(target,'w',compression=zipfile.ZIP_DEFLATED) as z:
        for name in include:
            p=out_dir/name
            if p.exists():z.write(p,arcname=name)
        z.write(SOURCE,arcname=SOURCE.name)
    return target

# ------------------------------- runner ------------------------------------
def run_parallel(tasks,worker,workers):
    if not tasks:return []
    if int(workers)<=1:return [worker(t) for t in tasks]
    ctx=mp.get_context('spawn'); out=[]
    with concurrent.futures.ProcessPoolExecutor(max_workers=int(workers),mp_context=ctx) as ex:
        futs={ex.submit(worker,t):t for t in tasks}
        for f in concurrent.futures.as_completed(futs):out.append(f.result())
    return out

def main(argv=None):
    ap=argparse.ArgumentParser(description=__doc__,formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument('--self-test',action='store_true'); ap.add_argument('--engineering-check',action='store_true')
    ap.add_argument('--stage',choices=('development','primary','scale','full','aggregate'),default='full')
    ap.add_argument('--out-dir',type=Path,default=Path('v46_results')); ap.add_argument('--workers',type=int,default=int(os.environ.get('V46_WORKERS','4')))
    ap.add_argument('--seeds',type=int,help='Non-scientific prefix of science roster.'); ap.add_argument('--smoke',action='store_true'); ap.add_argument('--skip-engineering',action='store_true')
    args=ap.parse_args(argv)
    if args.self_test:
        print(json.dumps(static_self_test(),indent=2,sort_keys=True)); return 0
    out=args.out_dir; out.mkdir(parents=True,exist_ok=True)
    seeds=list(ENGINEERING_SEEDS[:2] if args.smoke else (SCIENCE_SEEDS[:args.seeds] if args.seeds else SCIENCE_SEEDS)); scientific=not args.smoke and args.seeds is None
    if args.engineering_check:
        print(json.dumps(engineering_check(out,args.workers),indent=2,sort_keys=True)); return 0
    if args.stage in ('full','primary') and scientific and not args.skip_engineering and not (out/'RESUME_AUDIT.json').exists():
        print('Running required engineering/resume audit...',flush=True); engineering_check(out,args.workers)
    if args.stage in ('development','primary','scale','full'):
        tasks=[(s,str(out),args.smoke) for s in seeds]; print(f'Development: {len(tasks)} seeds, workers={args.workers}',flush=True)
        for r in run_parallel(tasks,run_development_worker,args.workers):print('  dev',r,flush=True)
    if args.stage in ('primary','full'):
        load=64 if args.smoke else PRIMARY_LOAD; tasks=[(s,load,str(out),args.smoke) for s in seeds]; print(f'Primary: load={load}, jobs={len(tasks)}',flush=True)
        for r in run_parallel(tasks,run_persistent_worker,args.workers):
            rr=r.get('result'); print('  primary',rr and {'seed':rr['seed'],'seconds':round(rr['elapsed_seconds'],1)},flush=True)
    if args.stage in ('scale','full') and not args.smoke:
        tasks=[(s,SECONDARY_LOAD,str(out),False) for s in seeds]; print(f'Scale: load={SECONDARY_LOAD}, jobs={len(tasks)}',flush=True)
        for r in run_parallel(tasks,run_persistent_worker,args.workers):
            rr=r.get('result'); print('  scale',rr and {'seed':rr['seed'],'seconds':round(rr['elapsed_seconds'],1)},flush=True)
    if args.stage in ('aggregate','primary','scale','full'):
        gates=aggregate(out,seeds); print('Verdict:',gates['verdict'],flush=True)
        if args.stage=='full' and scientific:
            z=package_upload(out); print('Upload bundle:',z,flush=True)
    return 0

if __name__=='__main__':raise SystemExit(main())
